<template><view class="wallet-center"><view class="account-profile"><view class="account-avatar"><image src="/static/ui/user.png"/></view><view><text class="account-title">{{ account.displayName || '我的會員帳戶' }}</text><text class="account-status">{{ account.memberId ? '會員編號 '+account.memberId : '尚未取得帳戶資料' }}</text></view></view><view class="wallet-heading"><text>我的餘額</text><text class="wallet-private">帳戶資產</text></view><view class="wallet-card points-wallet"><view class="wallet-caption"><view class="wallet-symbol">P</view><text>積分餘額</text></view><view class="wallet-value"><text class="wallet-number">{{ pointsText }}</text><text class="wallet-unit">積分</text></view><text class="wallet-note">可用於商品積分折抵</text></view><view class="wallet-card cash-wallet"><view class="wallet-caption"><view class="wallet-symbol">$</view><text>現金餘額</text></view><view class="wallet-value"><text class="currency">NT$</text><text class="wallet-number">{{ cashText }}</text></view><text class="wallet-note">帳戶可用現金</text></view><text v-if="account.points===null || account.cashCents===null" class="wallet-unavailable">餘額資訊目前無法顯示。</text><view class="benefit-summary"><text class="benefit-heading">會員積分禮遇</text><view><text>幸福會員</text><text>最高折抵30%</text></view><view><text>幸福VIP</text><text>最高可抵50%</text></view><text class="benefit-note">折抵需搭配足額積分。</text></view></view></template>
<script setup>
import {computed} from 'vue'
const props=defineProps({account:{type:Object,default:()=>({displayName:'',memberId:'',points:null,cashCents:null})}})
const pointsText=computed(()=>Number.isSafeInteger(props.account.points)&&props.account.points>=0?props.account.points.toLocaleString('en-US'):'—')
const cashText=computed(()=>Number.isSafeInteger(props.account.cashCents)&&props.account.cashCents>=0?(props.account.cashCents/100).toLocaleString('en-US',{minimumFractionDigits:props.account.cashCents%100?2:0,maximumFractionDigits:2}):'—')
</script>
<style scoped>.wallet-center{padding:24px 20px 35px}.account-profile{display:flex;align-items:center;gap:14px;margin:0 0 30px}.account-avatar{width:55px;height:55px;background:#e1f5ec;border:1px solid #d4eadf;border-radius:19px;display:flex;align-items:center;justify-content:center;flex-shrink:0}.account-avatar image{width:29px;height:29px}.account-title{display:block;font-size:22px;line-height:1.6;font-weight:700;color:#1f3b3c}.account-status{display:block;font-size:14px;color:#658074;line-height:1.7;margin-top:2px}.wallet-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;font-size:21px;font-weight:600;color:#233d40}.wallet-private{font-size:13px;font-weight:400;color:#73897c}.wallet-card{padding:22px;border-radius:21px;margin:0 0 16px;border:1px solid #d7ebe1}.points-wallet{background:linear-gradient(125deg,#e1f8ee,#effcf6)}.cash-wallet{background:#fff;border-color:#e0eae4}.wallet-caption{display:flex;align-items:center;gap:10px;font-size:18px;font-weight:600;color:#34584b}.wallet-symbol{width:30px;height:30px;border-radius:10px;background:#c8eddd;color:#008b70;line-height:30px;text-align:center;font-size:18px;font-weight:700}.cash-wallet .wallet-symbol{background:#edf3ee;color:#526c59}.wallet-value{display:flex;align-items:baseline;gap:10px;margin:15px 0 6px;color:#184635}.wallet-number{font-size:40px;font-weight:700;line-height:1.4;font-variant-numeric:tabular-nums}.wallet-unit,.currency{font-size:17px;color:#4e7160}.wallet-note{display:block;font-size:14px;line-height:1.8;color:#5f7c6c}.wallet-unavailable{display:block;font-size:14px;color:#6e8277;text-align:center;margin:10px 0 24px}.benefit-summary{background:white;border:1px solid #e2ebe5;border-radius:18px;padding:20px}.benefit-heading{display:block;font-size:19px;font-weight:600;color:#25453e;margin-bottom:10px}.benefit-summary>view{display:flex;justify-content:space-between;gap:12px;padding:12px 0;font-size:16px;color:#426050;border-bottom:1px solid #edf1ec}.benefit-note{display:block;font-size:13px;color:#75877b;margin-top:14px}</style>
